sources.SessionKeeper.ets:
@Component
export struct SessionKeeper {
 @State session: string = ''
 aboutToAppear(): void {
  this.session = AppStorage.get<string>('session.value') || ''
 }
 aboutToDisappear(): void {
  AppStorage.setOrCreate('session.value', this.session)
 }
 build() {}
}

sources.SessionWriter.ets:
export class SessionWriter {
 save(value: string): void {
  AppStorage.setOrCreate('session.value', value)
 }
}

sources.SessionReader.ets:
export class SessionReader {
 read(): string {
  return AppStorage.get<string>('session.value') || ''
 }
}
